
const WORDS=[{"id": 0, "w": "除夕", "p": "chúxī", "t": "名词", "m": "đêm giao thừa, trừ tịch", "coll": "除夕夜、过除夕", "s": "除夕晚上，我们一家人围坐在一起吃团圆饭。"}, {"id": 1, "w": "由来", "p": "yóulái", "t": "名词", "m": "nguồn gốc", "coll": "节日的由来、名字的由来", "s": "老师给我们讲了这个节日的由来。"}, {"id": 2, "w": "农历", "p": "nónglì", "t": "名词", "m": "âm lịch, Nông lịch", "coll": "农历新年、农历生日", "s": "奶奶一直按照农历过生日。"}, {"id": 3, "w": "守岁", "p": "shǒusuì", "t": "动词", "m": "đón giao thừa", "coll": "一起守岁、除夕守岁", "s": "除夕夜，一家人坐在电视机前一起守岁。"}, {"id": 4, "w": "怪物", "p": "guàiwù", "t": "名词", "m": "quái vật", "coll": "可怕的怪物、故事里的怪物", "s": "这个故事里有一个可怕的怪物。"}, {"id": 5, "w": "伤害", "p": "shānghài", "t": "动词", "m": "làm hại", "coll": "伤害别人、受到伤害", "s": "说话时要注意别伤害别人的感情。"}, {"id": 6, "w": "恨", "p": "hèn", "t": "动词", "m": "oán hận, căm ghét", "coll": "恨一个人、恨自己", "s": "他很恨自己当时没有勇气说出真相。"}, {"id": 7, "w": "骨头", "p": "gǔtou", "t": "名词", "m": "xương", "coll": "一根骨头、骨头受伤", "s": "医生仔细检查了他受伤的骨头。"}, {"id": 8, "w": "无奈", "p": "wúnài", "t": "动词", "m": "không biết làm sao, không có cách nào", "coll": "感到无奈、无奈地摇头", "s": "面对这样的结果，他只能无奈地摇了摇头。"}, {"id": 9, "w": "英雄", "p": "yīngxióng", "t": "名词", "m": "anh hùng", "coll": "民族英雄、成为英雄", "s": "孩子们认真地听着那位英雄的故事。"}, {"id": 10, "w": "英俊", "p": "yīngjùn", "t": "形容词", "m": "anh tuấn, khôi ngô", "coll": "英俊的青年、长得英俊", "s": "照片上的年轻人长得十分英俊。"}, {"id": 11, "w": "咬", "p": "yǎo", "t": "动词", "m": "cắn", "coll": "咬一口、被狗咬", "s": "弟弟轻轻地咬了一口苹果。"}, {"id": 12, "w": "外公", "p": "wàigōng", "t": "名词", "m": "ông ngoại", "coll": "我的外公、去外公家", "s": "放假的时候，我经常去外公家住几天。"}, {"id": 13, "w": "询问", "p": "xúnwèn", "t": "动词", "m": "hỏi thăm", "coll": "询问情况、向老师询问", "s": "她向工作人员询问了去车站的路。"}, {"id": 14, "w": "天真", "p": "tiānzhēn", "t": "形容词", "m": "ngây thơ, hồn nhiên", "coll": "天真的孩子、天真的想法", "s": "孩子用天真的眼神望着我，等我回答。"}, {"id": 15, "w": "杀", "p": "shā", "t": "动词", "m": "giết", "coll": "杀虫、杀死害虫", "s": "这种药是用来杀死害虫的。"}, {"id": 16, "w": "代替", "p": "dàitì", "t": "动词", "m": "thay thế", "coll": "代替别人、不能代替", "s": "机器不能完全代替人类的思考。"}, {"id": 17, "w": "除", "p": "chú", "t": "动词", "m": "trừ khử", "coll": "除掉杂草、除害", "s": "周末，我们一起除掉了院子里的杂草。"}, {"id": 18, "w": "制造", "p": "zhìzào", "t": "动词", "m": "gây ra, sản xuất", "coll": "制造产品、制造噪声", "s": "这家工厂主要制造汽车零件。"}, {"id": 19, "w": "灾害", "p": "zāihài", "t": "名词", "m": "tai họa", "coll": "自然灾害、遭受灾害", "s": "这次自然灾害给当地居民造成了很大的损失。"}, {"id": 20, "w": "逃", "p": "táo", "t": "动词", "m": "chạy trốn", "coll": "逃走、逃出房间", "s": "小猫趁门开着的时候，悄悄地逃了出去。"}, {"id": 21, "w": "影子", "p": "yǐngzi", "t": "名词", "m": "bóng dáng", "coll": "自己的影子、树的影子", "s": "夕阳下，树的影子被拉得很长。"}, {"id": 22, "w": "此外", "p": "cǐwài", "t": "连词", "m": "ngoài ra, hơn nữa", "coll": "此外还要、此外还有", "s": "房间里有一张床；此外，还有一张小书桌。"}, {"id": 23, "w": "说不定", "p": "shuōbudìng", "t": "副词", "m": "có lẽ, có thể", "coll": "说不定会下雨、说不定有机会", "s": "天阴得厉害，说不定一会儿就要下雨。"}, {"id": 24, "w": "熬夜", "p": "áo yè", "t": "动词", "m": "thức khuya", "coll": "经常熬夜、熬夜工作", "s": "为了准备明天的考试，他又熬夜了。"}, {"id": 25, "w": "赶紧", "p": "gǎnjǐn", "t": "副词", "m": "ngay lập tức", "coll": "赶紧出发、赶紧回家", "s": "快下雨了，我们赶紧回家吧。"}, {"id": 26, "w": "果然", "p": "guǒrán", "t": "副词", "m": "quả nhiên", "coll": "果然如此、果然成功了", "s": "天气预报说今天会下雨，下午果然下起雨来了。"}, {"id": 27, "w": "姑娘", "p": "gūniang", "t": "名词", "m": "cô gái, thiếu nữ", "coll": "一位姑娘、年轻的姑娘", "s": "那位姑娘笑着向我们介绍她的家乡。"}, {"id": 28, "w": "锅", "p": "guō", "t": "名词", "m": "(cái) nồi", "coll": "一口锅、锅里的汤", "s": "妈妈用这口锅煮了一锅热汤。"}, {"id": 29, "w": "盆子", "p": "pénzi", "t": "名词", "m": "chậu, bồn", "coll": "一个盆子、洗脸盆", "s": "她把洗好的衣服放进了盆子里。"}, {"id": 30, "w": "整个", "p": "zhěnggè", "t": "形容词", "m": "cả", "coll": "整个城市、整个过程", "s": "整个上午，他都在图书馆里看书。"}, {"id": 31, "w": "吓", "p": "xià", "t": "动词", "m": "làm cho khiếp sợ", "coll": "吓一跳、吓坏了", "s": "突然响起的雷声把孩子吓了一跳。"}, {"id": 32, "w": "似的", "p": "shìde", "t": "助词", "m": "dường như, tựa như", "coll": "像……似的、好像……似的", "s": "她高兴得像个孩子似的。"}, {"id": 33, "w": "追", "p": "zhuī", "t": "动词", "m": "đuổi theo", "coll": "追上同学、追着跑", "s": "弟弟在院子里追着小狗跑。"}, {"id": 34, "w": "箭", "p": "jiàn", "t": "名词", "m": "mũi tên", "coll": "一支箭、弓箭", "s": "他从箭袋里取出了一支箭。"}, {"id": 35, "w": "射击", "p": "shèjī", "t": "动词", "m": "bắn", "coll": "射击比赛、练习射击", "s": "运动员们正在为明天的比赛练习射击。"}, {"id": 36, "w": "纷纷", "p": "fēnfēn", "t": "形容词／副词", "m": "tới tấp, nhao nhao", "coll": "纷纷表示、纷纷离开", "s": "听完老师的话，同学们纷纷举手发言。"}, {"id": 37, "w": "表达", "p": "biǎodá", "t": "动词", "m": "bày tỏ, giải bày", "coll": "表达感谢、表达想法", "s": "他用一封信表达了对老师的感谢。"}, {"id": 38, "w": "意义", "p": "yìyì", "t": "名词", "m": "ý nghĩa, tầm quan trọng", "coll": "重要意义、词语的意义", "s": "这次活动对我们有着特别的意义。"}, {"id": 39, "w": "鞭炮", "p": "biānpào", "t": "名词", "m": "pháo", "coll": "放鞭炮、鞭炮声", "s": "故事里的村民通过放鞭炮庆祝新年的到来。"}, {"id": 40, "w": "风俗", "p": "fēngsú", "t": "名词", "m": "phong tục, tục lệ", "coll": "传统风俗、当地的风俗", "s": "旅行前，我们应该了解当地的风俗。"}];
const CHUNKS=[["除夕晚上，", "我们一家人", "围坐在一起", "吃团圆饭。"], ["老师", "给我们", "讲了", "这个节日的由来。"], ["奶奶", "一直", "按照农历", "过生日。"], ["除夕夜，", "一家人", "坐在电视机前", "一起守岁。"], ["这个故事里", "有", "一个", "可怕的怪物。"], ["说话时", "要注意", "别", "伤害别人的感情。"], ["他", "很恨自己", "当时", "没有勇气说出真相。"], ["医生", "仔细检查了", "他", "受伤的骨头。"], ["面对", "这样的结果，", "他", "只能无奈地摇了摇头。"], ["孩子们", "认真地", "听着", "那位英雄的故事。"], ["照片上的年轻人", "长得", "十分", "英俊。"], ["弟弟", "轻轻地", "咬了一口", "苹果。"], ["放假的时候，", "我", "经常", "去外公家住几天。"], ["她", "向工作人员", "询问了", "去车站的路。"], ["孩子", "用天真的眼神", "望着我，", "等我回答。"], ["这种药", "是", "用来", "杀死害虫的。"], ["机器", "不能", "完全代替", "人类的思考。"], ["周末，", "我们", "一起", "除掉了院子里的杂草。"], ["这家工厂", "主要", "制造", "汽车零件。"], ["这次自然灾害", "给当地居民", "造成了", "很大的损失。"], ["小猫", "趁门开着的时候，", "悄悄地", "逃了出去。"], ["夕阳下，", "树的影子", "被", "拉得很长。"], ["房间里", "有一张床；", "此外，", "还有一张小书桌。"], ["天", "阴得厉害，", "说不定", "一会儿就要下雨。"], ["为了", "准备明天的考试，", "他", "又熬夜了。"], ["快下雨了，", "我们", "赶紧", "回家吧。"], ["天气预报说", "今天会下雨，", "下午", "果然下起雨来了。"], ["那位姑娘", "笑着", "向我们", "介绍她的家乡。"], ["妈妈", "用这口锅", "煮了", "一锅热汤。"], ["她", "把洗好的衣服", "放进了", "盆子里。"], ["整个上午，", "他", "都在图书馆里", "看书。"], ["突然响起的雷声", "把", "孩子", "吓了一跳。"], ["她", "高兴得", "像个孩子", "似的。"], ["弟弟", "在院子里", "追着", "小狗跑。"], ["他", "从箭袋里", "取出了", "一支箭。"], ["运动员们", "正在", "为明天的比赛", "练习射击。"], ["听完老师的话，", "同学们", "纷纷", "举手发言。"], ["他", "用一封信", "表达了", "对老师的感谢。"], ["这次活动", "对我们", "有着", "特别的意义。"], ["故事里的村民", "通过", "放鞭炮", "庆祝新年的到来。"], ["旅行前，", "我们", "应该", "了解当地的风俗。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai6-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===3?WORDS.length:g*10+10);
const groupOf=id=>Math.min(3,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/41 个词语。学完四组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),41)}<div class="ntc-progressgroups">${[0,1,2,3].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共41个词语，点击 ↗ 学习该词语',totalLearned()+'/41 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为四组：10、10、10、11个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===40;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<40){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:3,idx:10};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课41个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课41个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [4, 19, 34], "1": [4, 19, 34], "2": [4, 19, 34], "3": [4, 19, 34], "4": [4, 19, 34], "5": [4, 19, 34], "6": [4, 19, 34], "7": [4, 19, 34], "8": [0, 34, 28], "9": [4, 19, 34], "10": [4, 19, 34], "11": [4, 19, 34], "12": [4, 19, 34], "13": [4, 19, 34], "14": [0, 34, 28], "15": [4, 19, 34], "16": [4, 19, 34], "17": [4, 19, 34], "18": [4, 19, 34], "19": [4, 19, 34], "20": [4, 19, 34], "21": [4, 19, 34], "22": [4, 19, 34], "23": [4, 19, 34], "24": [4, 19, 34], "25": [4, 19, 34], "26": [4, 19, 34], "27": [4, 19, 34], "28": [4, 19, 34], "29": [8, 23, 25], "30": [4, 19, 34], "31": [4, 19, 34], "32": [4, 19, 34], "33": [4, 19, 34], "34": [4, 19, 34], "35": [8, 23, 25], "36": [4, 19, 34], "37": [4, 19, 34], "38": [23, 25, 26], "39": [4, 19, 34], "40": [4, 19, 34]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的41个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第6课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第6课学习进度','第6课 · 41个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 41</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2,3].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第6课';$('ntc-bookmark').textContent=student?total+'/41 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2,3].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2,3].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第6课学习进度</div><div style="padding:0 10px">'+total+'/41 个已学词语'+meter(total,41)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"除夕":"data:audio/mpeg;base64,","除夕晚上，我们一家人围坐在一起吃团圆饭。":"data:audio/mpeg;base64,","由来":"data:audio/mpeg;base64,","老师给我们讲了这个节日的由来。":"data:audio/mpeg;base64,","农历":"data:audio/mpeg;base64,","奶奶一直按照农历过生日。":"data:audio/mpeg;base64,","守岁":"data:audio/mpeg;base64,","除夕夜，一家人坐在电视机前一起守岁。":"data:audio/mpeg;base64,","怪物":"data:audio/mpeg;base64,","这个故事里有一个可怕的怪物。":"data:audio/mpeg;base64,","伤害":"data:audio/mpeg;base64,","说话时要注意别伤害别人的感情。":"data:audio/mpeg;base64,","恨":"data:audio/mpeg;base64,","他很恨自己当时没有勇气说出真相。":"data:audio/mpeg;base64,","骨头":"data:audio/mpeg;base64,","医生仔细检查了他受伤的骨头。":"data:audio/mpeg;base64,","无奈":"data:audio/mpeg;base64,","面对这样的结果，他只能无奈地摇了摇头。":"data:audio/mpeg;base64,","英雄":"data:audio/mpeg;base64,","孩子们认真地听着那位英雄的故事。":"data:audio/mpeg;base64,","英俊":"data:audio/mpeg;base64,","照片上的年轻人长得十分英俊。":"data:audio/mpeg;base64,","咬":"data:audio/mpeg;base64,","弟弟轻轻地咬了一口苹果。":"data:audio/mpeg;base64,","外公":"data:audio/mpeg;base64,","放假的时候，我经常去外公家住几天。":"data:audio/mpeg;base64,","询问":"data:audio/mpeg;base64,","她向工作人员询问了去车站的路。":"data:audio/mpeg;base64,","天真":"data:audio/mpeg;base64,","孩子用天真的眼神望着我，等我回答。":"data:audio/mpeg;base64,","杀":"data:audio/mpeg;base64,","这种药是用来杀死害虫的。":"data:audio/mpeg;base64,","代替":"data:audio/mpeg;base64,","机器不能完全代替人类的思考。":"data:audio/mpeg;base64,","除":"data:audio/mpeg;base64,","周末，我们一起除掉了院子里的杂草。":"data:audio/mpeg;base64,","制造":"data:audio/mpeg;base64,","这家工厂主要制造汽车零件。":"data:audio/mpeg;base64,","灾害":"data:audio/mpeg;base64,","这次自然灾害给当地居民造成了很大的损失。":"data:audio/mpeg;base64,","逃":"data:audio/mpeg;base64,","小猫趁门开着的时候，悄悄地逃了出去。":"data:audio/mpeg;base64,","影子":"data:audio/mpeg;base64,","夕阳下，树的影子被拉得很长。":"data:audio/mpeg;base64,","此外":"data:audio/mpeg;base64,","房间里有一张床；此外，还有一张小书桌。":"data:audio/mpeg;base64,","说不定":"data:audio/mpeg;base64,","天阴得厉害，说不定一会儿就要下雨。":"data:audio/mpeg;base64,","熬夜":"data:audio/mpeg;base64,","为了准备明天的考试，他又熬夜了。":"data:audio/mpeg;base64,","赶紧":"data:audio/mpeg;base64,","快下雨了，我们赶紧回家吧。":"data:audio/mpeg;base64,","果然":"data:audio/mpeg;base64,","天气预报说今天会下雨，下午果然下起雨来了。":"data:audio/mpeg;base64,","姑娘":"data:audio/mpeg;base64,","那位姑娘笑着向我们介绍她的家乡。":"data:audio/mpeg;base64,","锅":"data:audio/mpeg;base64,","妈妈用这口锅煮了一锅热汤。":"data:audio/mpeg;base64,","盆子":"data:audio/mpeg;base64,","她把洗好的衣服放进了盆子里。":"data:audio/mpeg;base64,","整个":"data:audio/mpeg;base64,","整个上午，他都在图书馆里看书。":"data:audio/mpeg;base64,","吓":"data:audio/mpeg;base64,","突然响起的雷声把孩子吓了一跳。":"data:audio/mpeg;base64,","似的":"data:audio/mpeg;base64,","她高兴得像个孩子似的。":"data:audio/mpeg;base64,","追":"data:audio/mpeg;base64,","弟弟在院子里追着小狗跑。":"data:audio/mpeg;base64,","箭":"data:audio/mpeg;base64,","他从箭袋里取出了一支箭。":"data:audio/mpeg;base64,","射击":"data:audio/mpeg;base64,","运动员们正在为明天的比赛练习射击。":"data:audio/mpeg;base64,","纷纷":"data:audio/mpeg;base64,","听完老师的话，同学们纷纷举手发言。":"data:audio/mpeg;base64,","表达":"data:audio/mpeg;base64,","他用一封信表达了对老师的感谢。":"data:audio/mpeg;base64,","意义":"data:audio/mpeg;base64,","这次活动对我们有着特别的意义。":"data:audio/mpeg;base64,","鞭炮":"data:audio/mpeg;base64,","故事里的村民通过放鞭炮庆祝新年的到来。":"data:audio/mpeg;base64,","风俗":"data:audio/mpeg;base64,","旅行前，我们应该了解当地的风俗。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai6-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai6_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai6-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=41)||!p.memory)throw Error();if(!confirm('恢复第6课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<41;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<4&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<41&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第6课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

